//! Worlds and systems made before the arid criterion (format version 10,
//! generated by the main branch at 96 x 48 pixels, rivers left out) must
//! still load, and re-choose the biomes they stored.

use mapgen::biome::Biome;
use mapgen::export::raw_data::load_layers;
use mapgen::preset::Preset;
use mapgen::system::read_system;
use std::path::PathBuf;

fn fixture() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/format10")
}

#[test]
fn a_system_made_by_main_reads() {
    let system = read_system(&fixture()).expect("system.json of format 10");
    assert!(
        system
            .bodies
            .iter()
            .any(|b| b.params.planet.rules.is_legacy())
    );
}

#[test]
fn a_world_made_by_main_keeps_its_biomes_in_detail_and_epochs() {
    let loaded = load_layers(&fixture().join("bodies/e")).expect("world of format 10");
    assert!(loaded.params.planet.rules.is_legacy());
    assert_eq!(loaded.lapse_rate, mapgen::climate::LEGACY_LAPSE_RATE);
    let stored = loaded.biomes.clone();
    let world = loaded.into_world();
    // Choosing again from the stored layers, as the detail tiles and the
    // epochs do, gives the stored base map (but where a lake or a river
    // was drawn, which the layers do not keep).
    let rules = &world.params.planet.rules;
    let (mut same, mut total) = (0, 0);
    for (i, &b) in stored.iter().enumerate() {
        if matches!(b, Biome::Lake | Biome::River) || b.is_lava() {
            continue;
        }
        total += 1;
        same += usize::from(rules.choose(world.biome_input(i)) == b);
    }
    assert!(
        same as f32 > 0.99 * total as f32,
        "{same} of {total} biomes match"
    );
}

#[test]
fn regenerating_an_old_world_uses_the_current_model() {
    let loaded = load_layers(&fixture().join("bodies/e")).unwrap();
    let fresh = mapgen::generation::generate(&loaded.params).world;
    let rules = &fresh.params.planet.rules;
    assert!(!rules.is_legacy());
    assert_eq!(
        rules.forest_moisture,
        mapgen::biome::BiomeRules::default().forest_moisture
    );
    assert!(
        fresh
            .biomes
            .iter()
            .any(|b| *b == Biome::Shrubland || *b == Biome::Desert)
    );
}

#[test]
fn a_preset_with_the_former_cut_offs_is_accepted() {
    let text = "name = \"old\"\n[rules]\nshrubland_moisture = -0.1\ndesert_moisture = -0.05\n";
    let preset = Preset::from_toml(text, "old.toml").expect("accepted with a warning");
    assert!(!preset.rules.is_legacy());
    assert_eq!(preset.rules.desert_ratio, 5.0);
}
